import{_ as e,o as s,c as o,a2 as a}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Testing & Benchmarks — OpenShield-L7","description":"The OpenShield-L7 test battery — 215 unit tests, 85 e2e assertions, 8 attack scenarios with measured results, and how to reproduce with testing/run_all.sh.","frontmatter":{"title":"Testing & Benchmarks — OpenShield-L7","description":"The OpenShield-L7 test battery — 215 unit tests, 85 e2e assertions, 8 attack scenarios with measured results, and how to reproduce with testing/run_all.sh.","outline":"deep"},"headers":[],"relativePath":"openshield-l7/architecture/testing.md","filePath":"openshield-l7/architecture/testing.md","lastUpdated":1786524249000}'),d={name:"openshield-l7/architecture/testing.md"};function n(r,t,i,l,c,h){return s(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="testing-benchmarks" tabindex="-1">Testing &amp; Benchmarks <a class="header-anchor" href="#testing-benchmarks" aria-label="Permalink to &quot;Testing &amp; Benchmarks&quot;">​</a></h1><p>OpenShield-L7 ships with an automated battery that builds the release binary, spins up real proxy instances and test origins on temp roots, runs the full e2e assertion suite, then floods the proxy with six attack tools on both loopback and the LAN address. Everything below is measured output from <code>testing/run_all.sh</code> (<code>testing/RESULTS.md</code>, generated 2026-08-12).</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Command</th><th>Coverage</th></tr></thead><tbody><tr><td>Unit tests</td><td><code>cargo test --workspace</code></td><td><strong>215 tests</strong> across the seven crates — config validation, challenge crypto, client-IP resolution, limiters, WAF families, API handlers.</td></tr><tr><td>Lint</td><td><code>cargo clippy --workspace --all-targets</code></td><td>Clippy-clean.</td></tr><tr><td>E2E + attacks</td><td><code>testing/run_all.sh</code></td><td>85 e2e assertions + 8 attack scenarios against a running proxy. Needs root (the transparent-mode case); uses only high ports on loopback + the LAN address. Exits non-zero on any failure.</td></tr></tbody></table><hr><h2 id="e2e-battery-85-85-passed" tabindex="-1">E2E battery: 85 / 85 passed <a class="header-anchor" href="#e2e-battery-85-85-passed" aria-label="Permalink to &quot;E2E battery: 85 / 85 passed&quot;">​</a></h2><p>The battery covers the whole surface of the proxy. Grouped summary of the 77 assertions (all PASS):</p><table tabindex="0"><thead><tr><th>Area</th><th>Assertions</th><th>Highlights</th></tr></thead><tbody><tr><td>Routing</td><td>1–9, 55</td><td>Exact + deep wildcard hosts, bare domain not matched by wildcard, unknown host / bare IP → 421, disabled site → 503, case/port/trailing-dot tolerance, API delete → 421.</td></tr><tr><td>TLS</td><td>10–15</td><td>HTTP→HTTPS 308 with path+query preserved, SNI per-site certs, HSTS header, unknown SNI aborts the handshake.</td></tr><tr><td>Client IP</td><td>16–22</td><td>XFF default mode, untrusted inbound XFF discarded, trusted proxy chain walked + peer appended, <code>none</code> strips all client headers, <code>x_real_ip</code>, custom header, <code>X-Forwarded-Proto</code> set.</td></tr><tr><td>WAF</td><td>23–27, 67</td><td>Canonical payloads blocked with rule ids, <strong>zero false positives</strong> on benign lookalikes, double-encoded traversal blocked, scanner UA blocked, SQLi in POST body blocked.</td></tr><tr><td>Rate / conn limits</td><td>28–32, 62–63</td><td>Per-IP limit trips at the configured count (429) and recovers after the window; conn gauges stay exact under early-413 floods; per-IP conn cap under held connections; gauges released after completion. Bans outrank everything (huge POST from a banned IP → 403 <code>ban</code>, not 413).</td></tr><tr><td>PoW challenge</td><td>33–41</td><td>No-cookie request gets the PoW page; wrong nonce → 403; solved PoW → 200 + clearance cookie; clearance passes until expiry; garbage cookie still challenged; <strong>forged seed → 403 despite solved nonce</strong>; stale (11 min) seed → 403.</td></tr><tr><td>Quotas &amp; speed caps</td><td>42–44</td><td>Monthly quota → 509 after crossing; counters visible in stats; <code>max_site_bps</code> measured at the configured rate (400 KiB/s vs cap 400 KiB/s).</td></tr><tr><td>Admin API &amp; roles</td><td>45–57</td><td>Health unauthenticated; missing/bad token → 401; readonly GET ok, POST → 403; operator <code>PUT /global</code> → 403; site CRUD incl. PATCH disable/enable; invalid site → 400 with full <code>details</code>; <code>/global</code> redacts tokens and a <code>&quot;***&quot;</code> round-trip preserves them.</td></tr><tr><td>Hot reload</td><td>58–60</td><td>Invalid edit leaves other sites unaffected and keeps the broken site&#39;s last good config; reload reports the broken file; the fixed file hot-applies.</td></tr><tr><td>Bans</td><td>61–65</td><td>Manual ban blocks one IP only; list + DELETE lifts it; DELETE of a nonexistent ban → 404.</td></tr><tr><td>Stats / analytics / SSE</td><td>66–68</td><td>Global counters match generated traffic; analytics tops plausible; SSE emits request events.</td></tr><tr><td>Protocol behavior</td><td>69, 79–81</td><td>HTTP/1.1 keep-alive ×50; PROXY protocol v1 and v2 deliver the client endpoint; trusted XFF feeds the PROXY source (port 0 = unknown).</td></tr><tr><td>WebSockets</td><td>70–78</td><td>Upgrade pass-through; text+binary echo incl. a 1 MiB frame; 50 concurrent tunnels; tunnels counted in <code>active_connections</code> until close; keepalives beat <code>idle_timeout</code>, silence closes; <code>max_lifetime</code> caps a busy tunnel; <code>websockets.enabled: false</code> → 403 <code>websocket.disabled</code>; handshake rate-limited, established tunnel unaffected.</td></tr><tr><td>Transparent mode</td><td>82–83</td><td>Origin sees the real client IP (<code>10.255.255.7</code>) with <strong>no XFF header at all</strong>; trusted XFF resolves through to the bound source.</td></tr><tr><td>CLI &amp; shutdown</td><td>84–85</td><td><code>validate</code> reports all configs valid; graceful SIGTERM mid-download drains in a bounded 5 s and exits 0.</td></tr></tbody></table><hr><h2 id="attack-simulation-8-8-passed" tabindex="-1">Attack simulation: 8 / 8 passed <a class="header-anchor" href="#attack-simulation-8-8-passed" aria-label="Permalink to &quot;Attack simulation: 8 / 8 passed&quot;">​</a></h2><p>Six attack tools against the running proxy, on loopback (<code>127.0.0.1:18080</code>) and the LAN address (<code>192.168.1.103:18080</code>), while benign traffic flows to a neighboring site.</p><table tabindex="0"><thead><tr><th>Attack</th><th>Target</th><th>Mitigation observed</th><th>Verdict</th></tr></thead><tbody><tr><td>HTTP flood</td><td>loopback</td><td><strong>152,735 rps</strong>, 918,247 requests → 100% 429; benign site 100% 200 (p95 2.3 ms); RSS 43 MB → 61 MB</td><td>PASS</td></tr><tr><td>HTTP flood</td><td>LAN</td><td><strong>144,576 rps</strong>, 579,467 requests → 100% 429; benign 100% 200 (p95 2.4 ms)</td><td>PASS</td></tr><tr><td>Random-Host flood</td><td>loopback</td><td><strong>150,426 rps</strong> → 100% 421; legitimate site&#39;s request count untouched</td><td>PASS</td></tr><tr><td>Random-Host flood</td><td>LAN</td><td><strong>137,801 rps</strong> → 100% 421; legitimate site untouched</td><td>PASS</td></tr><tr><td>POST flood</td><td>loopback</td><td>Content-Length over cap → 413; chunked cut off after 1 MB streamed; sustained 25/25 413s; RSS growth 0.8 MB</td><td>PASS</td></tr><tr><td>Slowloris</td><td>loopback</td><td>300 trickling connections held 12 s; benign 100% 200 (p95 1.5 ms); post-attack status 200</td><td>PASS</td></tr><tr><td>WAF sweep</td><td>loopback</td><td>Canonical 100% (72/72), single-encoded 100%, double-encoded 35% (known gap), false positives 0/20</td><td>PASS</td></tr><tr><td>XFF spoofing</td><td>loopback</td><td>Untrusted rotation: 10× 429 (limiter holds — spoofed XFF ignored); trusted rotation: 0× 429 (per-IP buckets); trusted single-IP: 5× 429; telemetry shows the resolved IP</td><td>PASS</td></tr></tbody></table><h3 id="performance-sanity-loopback-protections-on" tabindex="-1">Performance sanity (loopback, protections ON) <a class="header-anchor" href="#performance-sanity-loopback-protections-on" aria-label="Permalink to &quot;Performance sanity (loopback, protections ON)&quot;">​</a></h3><ul><li>Proxied throughput (Rust fast origin): <strong>67,666 rps</strong> — p50 0.66 ms, p99 1.88 ms, max 8 ms.</li><li>541,881 requests, <strong>0 errors</strong>, all <code>200</code>.</li><li>Reference: the Python test origin alone caps at ~9,458 rps — it is the bottleneck in every python-origin measurement, not the proxy.</li></ul><h3 id="known-limitations-documented-measured" tabindex="-1">Known limitations (documented, measured) <a class="header-anchor" href="#known-limitations-documented-measured" aria-label="Permalink to &quot;Known limitations (documented, measured)&quot;">​</a></h3><ul><li><strong>Slowloris-class trickling</strong>: there is no header-read timeout; half-open connections are held indefinitely. Cost per connection is tiny (async runtime) and benign traffic is unaffected (verified above), but a header/read deadline would be cheap hardening.</li><li><strong>Double-encoded SQLi/XSS evade the content rules</strong>: the WAF percent-decodes once (documented design); only the path-traversal family treats leftover <code>%2e</code>/<code>%00</code> sequences as evasion markers — which is why double-encoded traversal still scores ~35% overall in the sweep.</li><li>The Python test origin (<code>testing/origin.py</code>) caps ~9k rps; every python-origin number above is origin-bound, not proxy-bound.</li></ul><hr><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to &quot;Reproduce&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># unit tests + lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clippy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-targets</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the full battery (needs root; idempotent; fresh temp root each run)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> testing/run_all.sh</span></span></code></pre></div><p>What <code>run_all.sh</code> does:</p><ol><li>Builds the release binary plus two Rust harness tools (<code>testing/bin/perfclient</code>, <code>testing/bin/fastorigin</code>).</li><li>Prepares fresh config roots (<code>testing/prep_roots.py</code>) and starts test origins (<code>testing/origin.py</code>, HTTP and PROXY-protocol modes).</li><li>Runs the 77-assertion e2e suite (<code>testing/e2e.py</code>).</li><li>Starts an attack proxy on <code>0.0.0.0:18080</code> and fires the attack tools in <code>testing/attacks/</code> — <code>http_flood.py</code>, <code>random_host_flood.py</code>, <code>post_flood.py</code>, <code>slowloris.py</code>, <code>waf_sweep.py</code>, <code>xff_spoof.py</code> — on loopback and the LAN address, while <code>perfclient</code> measures benign impact.</li><li>Renders <code>testing/RESULTS.md</code> (<code>render_results.py</code>), tears down all processes/routes on exit, and exits non-zero on any failure.</li></ol><p>Artifacts from each run are kept under <code>/tmp/osc-l7-run.*</code> (printed at the end).</p>`,22)])])}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
